insert into MST_CUSTOMER_INFO(CUSTOMER_ID, CUSTOMER_NAME, CUSTOMER_ABBR, CUSTOMER_TYPE, IS_ISSUER, IS_ASSTE_MANAGER, IS_TRUSTER, IS_SALER, IS_FINANCIER, IS_GUARANTEE, IS_RATING_AGENCIES, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME, IS_PLEDGOR, IS_DEPOSIT_BANK, IS_INVEST_ADVISER) select CUSTOMER_ID, CUSTOMER_NAME, CUSTOMER_ABBR, CUSTOMER_TYPE, IS_ISSUER, IS_ASSTE_MANAGER, IS_TRUSTER, IS_SALER, IS_FINANCIER, IS_GUARANTEE, IS_RATING_AGENCIES, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME, IS_PLEDGOR, IS_DEPOSIT_BANK, IS_INVEST_ADVISER from ( select TEMP.* from (
SELECT #{item.customerName,jdbcType=VARCHAR} CUSTOMER_NAME, #{item.customerAbbr,jdbcType=VARCHAR} CUSTOMER_ABBR, #{item.customerType,jdbcType=VARCHAR} CUSTOMER_TYPE, #{item.isIssuer,jdbcType=VARCHAR} IS_ISSUER, #{item.isAssteManager,jdbcType=VARCHAR} IS_ASSTE_MANAGER, #{item.isTruster,jdbcType=VARCHAR} IS_TRUSTER, #{item.isSaler,jdbcType=VARCHAR} IS_SALER, #{item.isFinancier,jdbcType=VARCHAR} IS_FINANCIER, #{item.isGuarantee,jdbcType=VARCHAR} IS_GUARANTEE, #{item.isRatingAgencies,jdbcType=VARCHAR} IS_RATING_AGENCIES, #{item.isPledgor,jdbcType=VARCHAR} IS_PLEDGOR, #{item.isDepositBank,jdbcType=VARCHAR} IS_DEPOSIT_BANK, #{item.isInvestAdviser,jdbcType=VARCHAR} IS_INVEST_ADVISER, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.createDept,jdbcType=VARCHAR} CREATE_DEPT, NOW() CREATE_TIME, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, NOW() UPDATE_TIME, #{item.customerId,jdbcType=VARCHAR} CUSTOMER_ID FROM DUAL
) TEMP where not exisits (select 1 from MST_CUSTOMER_INFO CII where CII.CUSTOMER_ID = TEMP.CUSTOMER_ID) ) de ;
UPDATE MST_CUSTOMER_INFO as A, ( select CUSTOMER_NAME, CUSTOMER_ABBR, CUSTOMER_TYPE, IS_ISSUER, IS_ASSTE_MANAGER, IS_TRUSTER, IS_SALER, IS_FINANCIER, IS_GUARANTEE, IS_RATING_AGENCIES, IS_PLEDGOR, IS_DEPOSIT_BANK, IS_INVEST_ADVISER, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME from ( select TEMP.* from (
SELECT #{item.customerName,jdbcType=VARCHAR} CUSTOMER_NAME, #{item.customerAbbr,jdbcType=VARCHAR} CUSTOMER_ABBR, #{item.customerType,jdbcType=VARCHAR} CUSTOMER_TYPE, #{item.isIssuer,jdbcType=VARCHAR} IS_ISSUER, #{item.isAssteManager,jdbcType=VARCHAR} IS_ASSTE_MANAGER, #{item.isTruster,jdbcType=VARCHAR} IS_TRUSTER, #{item.isSaler,jdbcType=VARCHAR} IS_SALER, #{item.isFinancier,jdbcType=VARCHAR} IS_FINANCIER, #{item.isGuarantee,jdbcType=VARCHAR} IS_GUARANTEE, #{item.isRatingAgencies,jdbcType=VARCHAR} IS_RATING_AGENCIES, #{item.isPledgor,jdbcType=VARCHAR} IS_PLEDGOR, #{item.isDepositBank,jdbcType=VARCHAR} IS_DEPOSIT_BANK, #{item.isInvestAdviser,jdbcType=VARCHAR} IS_INVEST_ADVISER, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.createDept,jdbcType=VARCHAR} CREATE_DEPT, NOW() CREATE_TIME, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, NOW() UPDATE_TIME, #{item.customerId,jdbcType=VARCHAR} CUSTOMER_ID FROM DUAL
) TEMP ) de ) AS B set A.* = B.* where exisits (select 1 from MST_CUSTOMER_INFO CII where CII.CUSTOMER_ID = TEMP.CUSTOMER_ID);
